/* My Health Journal v1.0 enhancements.
   PDF export, CSV export, Medical Records UI, PIN toggles.
   Kept separate to preserve the original feature code. */

(function () {
  const byId = id => document.getElementById(id);
  const accountIndex = () => JSON.parse(localStorage.getItem('mhj:accounts') || '[]');

  /* ------------------------------------------------------------------ */
  /* Login sheet helpers                                                 */
  /* ------------------------------------------------------------------ */

  function toggleSheet(id, show) {
    const el = byId(id);
    if (el) el.hidden = !show;
  }

  function syncLoginOptions() {
    const email = localStorage.getItem('mhj:lastActive');
    const record = email ? JSON.parse(localStorage.getItem(`mhj:account:${email}`) || 'null') : null;
    if (byId('pinLoginBtn')) byId('pinLoginBtn').hidden = !record?.settings?.appLock;
    if (byId('biometricLoginBtn')) byId('biometricLoginBtn').hidden = !record?.settings?.biometric;
  }

  byId('openLoginSheet')?.addEventListener('click', () => {
    toggleSheet('pinSheet', false);
    toggleSheet('loginSheet', true);
  });
  byId('closeLoginSheet')?.addEventListener('click', () => toggleSheet('loginSheet', false));
  byId('pinLoginBtn')?.addEventListener('click', () => {
    toggleSheet('loginSheet', false);
    toggleSheet('pinSheet', true);
  });
  byId('closePinSheet')?.addEventListener('click', () => toggleSheet('pinSheet', false));
  byId('submitPinLogin')?.addEventListener('click', () => {
    const pin = byId('loginPin')?.value || '';
    const email = localStorage.getItem('mhj:lastActive');
    const record = email ? JSON.parse(localStorage.getItem(`mhj:account:${email}`) || 'null') : null;
    if (!record) return showToast('No recent account is available on this device');
    if (!record.settings?.appLock) return showToast('PIN login is disabled for this account');
    loginUser(email, null, pin);
    toggleSheet('pinSheet', false);
  });

  document.querySelectorAll('[data-recovery]').forEach(btn => {
    btn.addEventListener('click', () => {
      const type = btn.dataset.recovery;
      if (type === 'pin') showScreen('pin-reset');
      else showScreen('forgot');
    });
  });

  byId('switchAccountBtn')?.addEventListener('click', () => {
    const accounts = accountIndex();
    if (!accounts.length) return showToast('No registered accounts on this device');
    const email = prompt(`Choose an account:\n${accounts.join('\n')}`, accounts[0]);
    if (email && accounts.includes(email)) {
      byId('loginEmail').value = email;
      toggleSheet('loginSheet', true);
    }
  });

  /* ------------------------------------------------------------------ */
  /* Avatar menu                                                         */
  /* ------------------------------------------------------------------ */

  const avatar = byId('topAvatar');
  const avatarMenu = byId('avatarMenu');
  avatar?.addEventListener('click', e => {
    if (!APP.isLoggedIn) return;
    e.stopPropagation();
    avatarMenu.hidden = !avatarMenu.hidden;
  });
avatarMenu?.addEventListener('click', e => {
  const action = e.target.dataset.avatarAction;
  if (!action) return;

  if (action === 'account-management' || action === 'data-management' || action === 'settings') {
    // Pre-fill all settings UI from APP.settings before showing
    const summaryKeys = ['readingReminder', 'weeklySummary', 'fortnightlySummary', 'monthlySummary'];
    for (const k of summaryKeys) {
      const el = document.getElementById(k);
      if (el) el.checked = !!APP.settings[k];
    }
    const auto = document.getElementById('autoBackupDaily');
    if (auto) auto.checked = !!APP.settings.autoBackup;

    const interval = document.getElementById('autoBackupInterval');
    if (interval) {
      const value = String(APP.settings.autoBackupInterval === 'daily' ? 1 : APP.settings.autoBackupInterval || 1);
      const known = [...interval.options].some(o => o.value === value);
      interval.value = known ? value : 'custom';
      const label = document.getElementById('autoBackupDaysLabel');
      const daysInput = document.getElementById('autoBackupDays');
      if (label) label.hidden = known;
      if (daysInput) daysInput.value = known ? '' : value;
    }

    if (typeof renderDriveStatus === 'function') renderDriveStatus();
    document.getElementById('settingsModal')?.classList.add('open');
  }

  if (action === 'pdf') {
    if (typeof openExportDialog === 'function') {
      openExportDialog('Export PDF Report', 'Export PDF', (from, to) => {
        if (typeof exportPDF === 'function') exportPDF(from, to);
      });
    } else if (typeof exportPDF === 'function') {
      exportPDF('', '');
    }
  }

  if (action === 'medical-records') {
    document.getElementById('medicalRecordsModal')?.classList.add('open');
    const uploadBtn = document.getElementById('uploadMedicalRecordBtn');
    if (uploadBtn) uploadBtn.style.display = 'block';
    if (typeof loadMedicalRecords === 'function') loadMedicalRecords();
  }

  if (action === 'security') {
    document.getElementById('securityModal')?.classList.add('open');
  }

  if (action === 'logout') {
    if (typeof logoutUser === 'function') logoutUser();
  }
});

  /* ------------------------------------------------------------------ */
  /* History bulk selection                                              */
  /* ------------------------------------------------------------------ */

  function selectedReadings() {
    const ids = [...document.querySelectorAll('.history-select:checked')].map(x => x.dataset.id);
    return APP.readings.filter(r => ids.includes(String(r.id || r.timestamp)));
  }

  function updateBulkButtons() {
    const count = document.querySelectorAll('.history-select:checked').length;
    if (byId('historyBulk')) byId('historyBulk').hidden = !count;
    document.querySelectorAll('.history-select').forEach(cb => { cb.hidden = false; });
  }

  byId('selectAllHistory')?.addEventListener('change', e => {
    document.querySelectorAll('.history-select').forEach(x => { x.checked = e.target.checked; });
    updateBulkButtons();
  });

  byId('bulkDeleteBtn')?.addEventListener('click', () => {
    const selected = selectedReadings();
    if (!selected.length || !confirm(`Delete ${selected.length} selected readings?`)) return;
    const ids = new Set(selected.map(r => String(r.id || r.timestamp)));
    APP.readings = APP.readings.filter(r => !ids.has(String(r.id || r.timestamp)));
    saveData();
    renderHistory();
  });

  byId('bulkExportBtn')?.addEventListener('click', () => exportRowsCSV(selectedReadings(), 'selected_readings.csv'));
  document.addEventListener('change', e => {
    if (e.target.classList?.contains('history-select')) updateBulkButtons();
  });

  window.decorateHistoryItems = function () {
    const table=byId('historyTable'); if(!table)return;
    let toggle=byId('toggleHistorySelection');
    if(!toggle){toggle=document.createElement('button');toggle.id='toggleHistorySelection';toggle.className='btn-secondary';toggle.textContent='Select Readings';table.parentElement.prepend(toggle);toggle.addEventListener('click',()=>{table.classList.toggle('selection-mode');toggle.textContent=table.classList.contains('selection-mode')?'Done Selecting':'Select Readings';toggle.setAttribute('aria-pressed',String(table.classList.contains('selection-mode')));});}
    if(!table.querySelector('thead .selection-cell')){const th=document.createElement('th');th.className='selection-cell';th.textContent='Select';table.querySelector('thead tr').prepend(th);}
    table.querySelectorAll('tbody tr[data-reading-id]').forEach(item=>{
      if(item.querySelector('.history-select'))return;
      const cell=document.createElement('td');cell.className='selection-cell';
      const cb=document.createElement('input');cb.type='checkbox';cb.className='history-select';cb.dataset.id=item.dataset.readingId;cb.setAttribute('aria-label','Select reading');
      cell.addEventListener('click',e=>e.stopPropagation());cb.addEventListener('change',updateBulkButtons);cell.append(cb);item.prepend(cell);
      item.addEventListener('contextmenu',e=>{e.preventDefault();table.classList.add('selection-mode');toggle.textContent='Done Selecting';cb.checked=true;updateBulkButtons();});
    });
    updateBulkButtons();
  };

  /* ------------------------------------------------------------------ */
  /* CSV export (selection) — same header as reliability.js exportCSV    */
  /* ------------------------------------------------------------------ */

  function csvCell(v) {
    const s = String(v ?? '');
    return '"' + (/^[=+\-@\t\r]/.test(s) ? "'" : '') + s.replace(/"/g, '""') + '"';
  }

  function exportRowsCSV(rows, filename) {
    if (!rows.length) return showToast('No readings selected');
    const header = ['Date', 'Time', 'Window', 'Systolic', 'Diastolic', 'Pulse',
      'Glucose', 'Glucose Unit', 'Glucose Category', 'Glucose Classification',
      'Symptoms', 'Position', 'Arm', 'Medication', 'Meal', 'Activity', 'Intake', 'Notes'];
    const lines = rows.map(r => {
      const d = new Date(r.timestamp);
      return [
        d.toLocaleDateString(), d.toLocaleTimeString(), r.window,
        isPresent(r.sys) ? r.sys : null,
        isPresent(r.dia) ? r.dia : null,
        isPresent(r.pulse) ? r.pulse : null,
        isPresent(r.glucoseValue) ? r.glucoseValue : null,
        isPresent(r.glucoseValue) ? (r.glucoseUnit || 'mg/dL') : null,
        r.glucoseCategory || null,
        getGlucoseStatus(r.glucoseValue, r.glucoseCategory, r.glucoseUnit).classification,
        r.symptoms, r.position, r.arm, r.medication, r.meal, r.activity, r.intake, r.extraNote
      ].map(csvCell).join(',');
    });
    downloadFile('\ufeff' + [header.join(','), ...lines].join('\r\n'), filename, 'text/csv;charset=utf-8');
    showToast('CSV downloaded; Drive upload in progress');
  }

  /* ------------------------------------------------------------------ */
  /* About modal + version                                               */
  /* ------------------------------------------------------------------ */

  async function fetchAppVersion() {
    try {
      const response = await fetch('manifest.json');
      if (!response.ok) throw new Error('Manifest not found');
      const manifest = await response.json();
      return manifest.version || 'v1.0.0';
    } catch (error) {
      console.warn('Could not fetch manifest, using fallback version:', error);
      return 'v1.0.0';
    }
  }

  async function updateAboutModal() {
    const versionEl = byId('aboutVersion');
    const yearEl = byId('aboutYear');
    if (yearEl) yearEl.textContent = new Date().getFullYear();
    if (versionEl) versionEl.textContent = await fetchAppVersion();
  }

  byId('openAboutBtn')?.addEventListener('click', async () => {
    byId('settingsModal')?.classList.remove('open');
    await updateAboutModal();
    byId('aboutModal')?.classList.add('open');
  });

  byId('closeAboutModal')?.addEventListener('click', () => byId('aboutModal')?.classList.remove('open'));

  /* ------------------------------------------------------------------ */
  /* Multi-select custom inputs                                          */
  /* ------------------------------------------------------------------ */

  ['recAct', 'recIntake'].forEach(id => byId(id)?.addEventListener('change', e => {
    const custom = byId(id === 'recAct' ? 'recCustomAct' : 'recCustomIntake');
    if (custom) custom.hidden = !Array.from(e.target.selectedOptions).some(o => o.value === 'Custom');
  }));

  syncLoginOptions();

  /* ------------------------------------------------------------------ */
  /* Chart layout sync (kept for compatibility with existing CSS)        */
  /* ------------------------------------------------------------------ */

  function syncChartLayout() {
    const mode = document.querySelector('.chart-option.active')?.dataset.chart || 'bp';
    const containers = document.querySelectorAll('#view-trends .chart-container');
    if (containers[0]) {
      containers[0].hidden = false;
      const title = containers[0].querySelector('h4');
      if (title) {
        title.textContent =
          mode === 'bp' ? 'Blood Pressure Trend' :
          mode === 'pulse' ? 'Pulse Trend' :
          mode === 'glucose' ? 'Glucose Trend' :
          'All Metrics';
      }
    }
    if (containers[1]) containers[1].hidden = true;
  }
  document.querySelectorAll('.chart-option').forEach(button => button.addEventListener('click', () => setTimeout(syncChartLayout, 0)));
  syncChartLayout();

  /* ================================================================== */
  /* PDF EXPORT — full rewrite                                           */
  /* ================================================================== */

  window.exportPDF = async function (fromDate, toDate, rowsOverride) {
    try {
      const rows = rowsOverride || getReadingsInRange(fromDate, toDate);
      if (!rows.length) return showToast('No readings to export');
      if (!window.jspdf?.jsPDF) return showToast('PDF library not loaded');

      showToast('Preparing PDF report...');
      const { jsPDF } = window.jspdf;

/* ---- colour helpers ---- */

function getStatusColor(sys, dia) {
  const status = getBPStatus(sys, dia);
  switch (status.class) {
    case 'status-crisis': return [185, 28, 28];      // dark red
    case 'status-stage2': return [120, 53, 15];      // dark brown
    case 'status-stage1': return [194, 65, 12];      // dark orange
    case 'status-elevated': return [161, 98, 7];     // dark amber
    case 'status-normal': return [21, 128, 61];      // dark green
    case 'status-hypotension': return [29, 78, 216]; // dark blue
    default: return [16, 26, 49];
  }
}

function getPulseColor(pulse) {
  if (!isPresent(pulse)) return [100, 116, 139];
  if (pulse > 120) return [185, 28, 28];      // dark red
  if (pulse >= 101) return [120, 53, 15];     // dark brown
  if (pulse >= 60) return [21, 128, 61];      // dark green
  if (pulse >= 40) return [161, 98, 7];       // dark amber
  return [194, 65, 12];                        // dark orange
}

function getGlucoseColor(value, category, unit) {
  const s = getGlucoseStatus(value, category, unit);
  switch (s.class) {
    case 'glucose-low': return [29, 78, 216];        // dark blue
    case 'glucose-normal': return [21, 128, 61];     // dark green
    case 'glucose-elevated': return [161, 98, 7];    // dark amber
    case 'glucose-high': return [185, 28, 28];       // dark red
    case 'glucose-hyper': return [120, 53, 15];      // dark brown
    default: return [100, 116, 139];
  }
}

      /* Split a classification label into "medical term" + "(plain word)". */
      function splitClassification(label) {
        if (!label || label === '--') return { line1: '--', line2: '' };
        const m = label.match(/^([^(]+?)\s*\(([^)]+)\)\s*$/);
        if (m) return { line1: m[1].trim(), line2: `(${m[2].trim()})` };
        return { line1: label.trim(), line2: '' };
      }

      /* ---- formatting helpers ---- */
      function formatDateForReport(date) {
        const d = new Date(date);
        const day = String(d.getDate()).padStart(2, '0');
        const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        const month = months[d.getMonth()];
        const year = String(d.getFullYear()).slice(-2);
        const time = d.toLocaleTimeString('en-US', { hour12: true, hour: '2-digit', minute: '2-digit', second: '2-digit' });
        return `${day} ${month} ${year}  |  ${time}`;
      }

      function formatDuration(days) {
        if (days < 1) return '0 days';
        if (days < 30) return `${days} days`;
        if (days < 365) {
          const months = Math.floor(days / 30);
          const remaining = days % 30;
          return remaining === 0 ? `${months} mon` : `${months} mon, ${remaining} days`;
        }
        const years = Math.floor(days / 365);
        const remainingMonths = Math.floor((days % 365) / 30);
        const remainingDays = days % 30;
        const parts = [`${years} yr`];
        if (remainingMonths > 0) parts.push(`${remainingMonths} mon`);
        if (remainingDays > 0) parts.push(`${remainingDays} days`);
        return parts.join(', ');
      }

      function calculateAgeDetails(dob) {
        if (!dob) return { years: 0, months: 0 };
        const birthDate = new Date(dob);
        const today = new Date();
        let years = today.getFullYear() - birthDate.getFullYear();
        let months = today.getMonth() - birthDate.getMonth();
        if (months < 0 || (months === 0 && today.getDate() < birthDate.getDate())) {
          years--;
          months += 12;
        }
        if (months < 0) months += 12;
        return { years, months };
      }

      /* ---- user details ---- */
      const user = APP.user || {};
      const name = user.name || 'Unknown';
      const email = user.email || 'Not provided';
      const phone = user.phone || 'Not provided';
      const dob = user.dob || null;
      const gender = user.gender || 'Not provided';
      const ageDetails = calculateAgeDetails(dob);
      const ageString = (ageDetails.years > 0 || ageDetails.months > 0)
        ? `${ageDetails.years > 0 ? ageDetails.years + ' yr' : ''}${ageDetails.years > 0 && ageDetails.months > 0 ? ', ' : ''}${ageDetails.months > 0 ? ageDetails.months + ' mon' : ''}`
        : 'N/A';

      /* ---- snapshot numbers ---- */
      const bpRows = rows.filter(hasBP);
      const sys = metricSummary(bpRows.map(r => r.sys));
      const dia = metricSummary(bpRows.map(r => r.dia));
      const pulse = metricSummary(rows.map(r => r.pulse));
      const days = measurementDays(rows, fromDate, toDate);
      const glucoseSummary = summariseGlucoseByCategory(rows, days);
      const bpScore = computeBPScore(rows, days);
      const pulseScore = computePulseScore(rows, days);

      let startDateStr = 'All';
      let endDateStr = 'All';
      if (rows.length > 0) {
        const sorted = [...rows].sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));
        startDateStr = formatDateForReport(new Date(sorted[0].timestamp));
        endDateStr = formatDateForReport(new Date(sorted[sorted.length - 1].timestamp));
      }

      const colors = {
        primary: [255, 131, 8],
        navy: [16, 26, 49],
        gray: [160, 174, 192],
        lightGray: [200, 204, 210],
        unitGrey: [148, 163, 184],
        white: [255, 255, 255],
        black: [26, 26, 26],
        borderGray: [220, 220, 220]
      };

      /* ---- page sizing ---- */
      const lineHeight = 5.5;
      const patientHeight = 8 + (6 * lineHeight);
      const reportHeight = 8 + (6 * lineHeight);
      /* Snapshot: header + BP/Pulse (6 rows) + glucose grid (6 rows + header + 4 extra for wrapped classifications) */
      const snapshotHeight = 16 + (16 * lineHeight);
      const tableHeaderHeight = 8;
      const tableRowsHeight = rows.length * 6.5;
      const footerHeight = 26;
      const totalContentHeight = 52 + patientHeight + 10 + reportHeight + 10 + snapshotHeight + 12 + tableHeaderHeight + tableRowsHeight + footerHeight;
      const pageHeight = Math.max(totalContentHeight, 297);

      const doc = new jsPDF({ orientation: 'p', unit: 'mm', format: [210, pageHeight] });
      const pageWidth = 210;
      const margin = 20;
      let y = 28;

      /* ---- watermark ---- */
      try {
        const wImg = new Image();
        wImg.crossOrigin = 'Anonymous';
        wImg.src = 'app-logo.png';
        await new Promise(resolve => {
          wImg.onload = resolve;
          wImg.onerror = resolve;
          setTimeout(resolve, 3000);
        });
        if (wImg.complete && wImg.naturalWidth > 0) {
          const w = 90;
          const h = (wImg.naturalHeight / wImg.naturalWidth) * w;
          doc.setGState(new doc.GState({ opacity: 0.08 }));
          doc.addImage(wImg, 'PNG', (pageWidth / 2) - (w / 2), (pageHeight / 2) - (h / 2), w, h);
          doc.setGState(new doc.GState({ opacity: 1.0 }));
        }
      } catch (e) { console.log('Watermark skipped:', e); }

      /* ---- header logo — top right ---- */
      try {
        const hImg = new Image();
        hImg.crossOrigin = 'Anonymous';
        hImg.src = 'reporting-logo.png';
        await new Promise(resolve => {
          hImg.onload = resolve;
          hImg.onerror = resolve;
          setTimeout(resolve, 3000);
        });
        if (hImg.complete && hImg.naturalWidth > 0) {
          const h = 22;
          const w = (hImg.naturalWidth / hImg.naturalHeight) * h;
          doc.addImage(hImg, 'PNG', pageWidth - margin - w, 6, w, h);
        }
      } catch (e) { console.log('Header logo skipped:', e); }

      /* ---- title — "My Health Journal" orange + " Report" black ---- */
      doc.setFontSize(21);
      doc.setFont('helvetica', 'bold');

      /* Measure without charSpace to keep positioning exact */
      const title1 = 'My Health Journal';
      const title2 = ' Report';
      const title1Width = doc.getTextWidth(title1);
      const title2Width = doc.getTextWidth(title2);
      const titleTotal = title1Width + title2Width;
      const titleX = (pageWidth - titleTotal) / 2;
      const titleBaselineY = 26;

      doc.setTextColor(...colors.primary);
      doc.text(title1, titleX, titleBaselineY);
      doc.setTextColor(...colors.black);
      doc.text(title2, titleX + title1Width, titleBaselineY);

      /* orange rule — exactly the width of the full title, centered */
      doc.setDrawColor(...colors.primary);
      doc.setLineWidth(0.6);
      doc.line(titleX, titleBaselineY + 3, titleX + titleTotal, titleBaselineY + 3);

      /* grey subtitle */
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(8.5);
      doc.setTextColor(...colors.gray);
      doc.text('Blood Pressure, Pulse & Blood Glucose Summary Report', pageWidth / 2, titleBaselineY + 9, { align: 'center' });

      /* space below title */
      y = 44;

      /* ---- two-column header: patient details + report details ---- */
      const leftColX = margin;
      const rightColX = 110;
      const labelColor = [160, 174, 192];
      const valueColor = [16, 26, 49];
      let leftY = y;
      let rightY = y;

      doc.setTextColor(...colors.black);
      doc.setFontSize(10);
      doc.setFont('helvetica', 'bold');
      doc.text('Patient Details', leftColX, leftY);
      leftY += 6;

      doc.setFont('helvetica', 'normal');
      doc.setFontSize(8.5);
      const patientFields = [
        ['Name:', name],
        ['DOB:', dob || 'Not provided'],
        ['Age:', ageString],
        ['Gender:', gender],
        ['Phone:', phone],
        ['Email:', email]
      ];
      patientFields.forEach(field => {
        doc.setTextColor(...labelColor);
        doc.setFontSize(8.5);
        doc.setFont('helvetica', 'normal');
        doc.text(field[0], leftColX, leftY);
        doc.setTextColor(...valueColor);
        doc.text(String(field[1]), leftColX + 20, leftY);
        leftY += lineHeight;
      });

      const fromStr = startDateStr;
      const toStr = endDateStr;
      const totalDays = fromDate && toDate
        ? Math.ceil((new Date(toDate) - new Date(fromDate)) / 86400000) + 1
        : days;
      const reportGenerated = formatDateForReport(new Date());

      doc.setTextColor(...colors.black);
      doc.setFontSize(10);
      doc.setFont('helvetica', 'bold');
      doc.text('Report Details', rightColX, rightY);
      rightY += 6;

      doc.setFont('helvetica', 'normal');
      doc.setFontSize(8.5);
      const reportFields = [
        ['Start Date:', fromStr],
        ['End Date:', toStr],
        ['Reporting Period:', formatDuration(totalDays)],
        ['Report Generated:', reportGenerated],
        ['Total Readings:', String(rows.length)]
      ];
      reportFields.forEach(field => {
        doc.setTextColor(...labelColor);
        doc.setFontSize(8.5);
        doc.setFont('helvetica', 'normal');
        doc.text(field[0], rightColX, rightY);
        doc.setTextColor(...valueColor);
        doc.text(String(field[1]), rightColX + 32, rightY);
        rightY += lineHeight;
      });

      y = Math.max(leftY, rightY) + 10;

      /* ---- SNAPSHOT ---- */
      doc.setTextColor(...colors.black);
      doc.setFontSize(12);
      doc.setFont('helvetica', 'bold');
      doc.text('Snapshot', margin, y);
      y += 7;

      const tierLabelColor = [160, 174, 192];
      const tierValueColor = [16, 26, 49];

      /* BP panel */
      let bpY = y;
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(9);
      doc.setTextColor(...colors.primary);
      doc.text('Blood Pressure', leftColX, bpY);
      const bpHeaderWidth = doc.getTextWidth('Blood Pressure');
      doc.setDrawColor(...colors.lightGray);
      doc.setLineWidth(0.3);
      doc.line(leftColX, bpY + 1.5, leftColX + bpHeaderWidth, bpY + 1.5);
      bpY += 6;

      const bpMetrics = [
        ['Average:', `${sys.average ?? '--'}/${dia.average ?? '--'} mmHg`],
        ['Highest:', `${sys.highest ?? '--'}/${dia.highest ?? '--'} mmHg`],
        ['Lowest:', `${sys.lowest ?? '--'}/${dia.lowest ?? '--'} mmHg`],
        ['Avg. Classification:', getBPStatus(sys.average, dia.average).label.replace(/[^\w\s()\-]/g, '').trim() || '--'],
        ['Readings Count:', String(sys.count || 0)],
        ['Score:', scoreText(bpScore)]
      ];
      bpMetrics.forEach(metric => {
        doc.setTextColor(...tierLabelColor);
        doc.setFontSize(8);
        doc.setFont('helvetica', 'normal');
        doc.text(metric[0], leftColX + 3, bpY);

        const full = String(metric[1]);
        const unitMatch = full.match(/^(.*?)(\s*(?:mmHg|BPM|mg\/dL))$/);
        if (unitMatch) {
          doc.setFont('helvetica', 'bold');
          doc.setFontSize(8);
          doc.setTextColor(...tierValueColor);
          doc.text(unitMatch[1], leftColX + 34, bpY);
          const valW = doc.getTextWidth(unitMatch[1]);
          doc.setFont('helvetica', 'normal');
          doc.setTextColor(...colors.unitGrey);
          doc.text(unitMatch[2], leftColX + 34 + valW, bpY);
        } else {
          doc.setFont('helvetica', 'bold');
          doc.setFontSize(8);
          doc.setTextColor(...tierValueColor);
          doc.text(full, leftColX + 34, bpY);
        }
        bpY += lineHeight;
      });

      /* Pulse panel */
      let pulseY = y;
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(9);
      doc.setTextColor(...colors.primary);
      doc.text('Pulse', rightColX, pulseY);
      const pulseHeaderWidth = doc.getTextWidth('Pulse');
      doc.setDrawColor(...colors.lightGray);
      doc.setLineWidth(0.3);
      doc.line(rightColX, pulseY + 1.5, rightColX + pulseHeaderWidth, pulseY + 1.5);
      pulseY += 6;

      const pulseMetrics = [
        ['Average:', `${pulse.average ?? '--'} BPM`],
        ['Highest:', `${pulse.highest ?? '--'} BPM`],
        ['Lowest:', `${pulse.lowest ?? '--'} BPM`],
        ['Avg. Classification:', getPulseStatus(pulse.average).label.replace(/[^\w\s()\-]/g, '').trim() || '--'],
        ['Readings Count:', String(pulse.count || 0)],
        ['Score:', scoreText(pulseScore)]
      ];
      pulseMetrics.forEach(metric => {
        doc.setTextColor(...tierLabelColor);
        doc.setFontSize(8);
        doc.setFont('helvetica', 'normal');
        doc.text(metric[0], rightColX + 3, pulseY);

        const full = String(metric[1]);
        const unitMatch = full.match(/^(.*?)(\s*(?:mmHg|BPM|mg\/dL))$/);
        if (unitMatch) {
          doc.setFont('helvetica', 'bold');
          doc.setFontSize(8);
          doc.setTextColor(...tierValueColor);
          doc.text(unitMatch[1], rightColX + 36, pulseY);
          const valW = doc.getTextWidth(unitMatch[1]);
          doc.setFont('helvetica', 'normal');
          doc.setTextColor(...colors.unitGrey);
          doc.text(unitMatch[2], rightColX + 36 + valW, pulseY);
        } else {
          doc.setFont('helvetica', 'bold');
          doc.setFontSize(8);
          doc.setTextColor(...tierValueColor);
          doc.text(full, rightColX + 36, pulseY);
        }
        pulseY += lineHeight;
      });

      /* vertical grey divider between BP and Pulse */
      const dividerX = (leftColX + rightColX) / 2 + 30;
      doc.setDrawColor(...colors.lightGray);
      doc.setLineWidth(0.3);
      doc.line(dividerX, y - 6, dividerX, Math.max(bpY, pulseY) - 2);

      y = Math.max(bpY, pulseY) + 8;

      /* ---- GLUCOSE GRID — categories as columns, stats as rows ---- */
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(9);
      doc.setTextColor(...colors.primary);
      doc.text('Blood Glucose', leftColX, y);
      const gHeaderWidth = doc.getTextWidth('Blood Glucose');
      doc.setDrawColor(...colors.lightGray);
      doc.setLineWidth(0.3);
      doc.line(leftColX, y + 1.5, leftColX + gHeaderWidth, y + 1.5);
      y += 6;

      const statColWidth = 34;
      const availWidth = pageWidth - (margin * 2) - statColWidth;
      const catColWidth = availWidth / 5;
      const tableLeft = margin;

      /* header row: category names */
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(8);
      doc.setTextColor(...tierValueColor);
      GLUCOSE_CATEGORIES.forEach((category, i) => {
        const xPos = tableLeft + statColWidth + (i * catColWidth);
        const label = GLUCOSE_LABELS[category];
        const textWidth = doc.getStringUnitWidth(label) * 8 / doc.internal.scaleFactor;
        const textX = xPos + (catColWidth / 2) - (textWidth / 2);
        doc.text(label, textX, y);
      });
      y += 6;

      /* stat rows */
      const statRows = [
        { label: 'Average:', key: 'average' },
        { label: 'Highest:', key: 'highest' },
        { label: 'Lowest:', key: 'lowest' },
        { label: 'Avg. Classification:', key: 'classification' },
        { label: 'Readings Count:', key: 'count' },
        { label: 'Score:', key: 'score' }
      ];

      statRows.forEach(row => {
        const rowStartY = y;

        /* row label */
        doc.setFont('helvetica', 'normal');
        doc.setFontSize(8);
        doc.setTextColor(...tierLabelColor);
        doc.text(row.label, tableLeft, rowStartY);

        /* one cell per category */
        GLUCOSE_CATEGORIES.forEach((category, i) => {
          const s = glucoseSummary.find(x => x.category === category);
          const xPos = tableLeft + statColWidth + (i * catColWidth);

          if (!s) {
            doc.setFont('helvetica', 'normal');
            doc.setFontSize(8);
            doc.setTextColor(...tierLabelColor);
            const tw = doc.getStringUnitWidth('--') * 8 / doc.internal.scaleFactor;
            doc.text('--', xPos + (catColWidth / 2) - (tw / 2), rowStartY);
            return;
          }

          if (row.key === 'average') {
            const text = formatGlucosePrimary(s.average, 'mg/dL');
            doc.setFont('helvetica', 'bold');
            doc.setFontSize(8);
            doc.setTextColor(...getGlucoseColor(s.average, category, 'mg/dL'));
            const tw = doc.getStringUnitWidth(text) * 8 / doc.internal.scaleFactor;
            doc.text(text, xPos + (catColWidth / 2) - (tw / 2), rowStartY);
          } else if (row.key === 'highest') {
            const text = formatGlucosePrimary(s.highest, 'mg/dL');
            doc.setFont('helvetica', 'bold');
            doc.setFontSize(8);
            doc.setTextColor(...tierValueColor);
            const tw = doc.getStringUnitWidth(text) * 8 / doc.internal.scaleFactor;
            doc.text(text, xPos + (catColWidth / 2) - (tw / 2), rowStartY);
          } else if (row.key === 'lowest') {
            const text = formatGlucosePrimary(s.lowest, 'mg/dL');
            doc.setFont('helvetica', 'bold');
            doc.setFontSize(8);
            doc.setTextColor(...tierValueColor);
            const tw = doc.getStringUnitWidth(text) * 8 / doc.internal.scaleFactor;
            doc.text(text, xPos + (catColWidth / 2) - (tw / 2), rowStartY);
          } else if (row.key === 'classification') {
            const label = getGlucoseStatus(s.average, category, 'mg/dL').label || '--';
            const parts = splitClassification(label);
            doc.setFont('helvetica', 'bold');
            doc.setFontSize(8);
            doc.setTextColor(...tierValueColor);
            const w1 = doc.getStringUnitWidth(parts.line1) * 8 / doc.internal.scaleFactor;
            doc.text(parts.line1, xPos + (catColWidth / 2) - (w1 / 2), rowStartY);
            if (parts.line2) {
              doc.setFont('helvetica', 'normal');
              doc.setFontSize(7);
              doc.setTextColor(...tierLabelColor);
              const w2 = doc.getStringUnitWidth(parts.line2) * 7 / doc.internal.scaleFactor;
              doc.text(parts.line2, xPos + (catColWidth / 2) - (w2 / 2), rowStartY + 3.5);
            }
          } else if (row.key === 'count') {
            doc.setFont('helvetica', 'bold');
            doc.setFontSize(8);
            doc.setTextColor(...tierValueColor);
            const text = String(s.count);
            const tw = doc.getStringUnitWidth(text) * 8 / doc.internal.scaleFactor;
            doc.text(text, xPos + (catColWidth / 2) - (tw / 2), rowStartY);
          } else if (row.key === 'score') {
            doc.setFont('helvetica', 'normal');
            doc.setFontSize(8);
            doc.setTextColor(...tierValueColor);
            const text = scoreText(s.score);
            const tw = doc.getStringUnitWidth(text) * 8 / doc.internal.scaleFactor;
            doc.text(text, xPos + (catColWidth / 2) - (tw / 2), rowStartY);
          }
        });

        /* advance — classification rows are taller because of the second line */
        y += (row.key === 'classification') ? lineHeight + 4 : lineHeight + 0.5;
      });

      y += 8;

      /* ---- CLINICAL READINGS ---- */
      doc.setTextColor(...colors.black);
      doc.setFontSize(12);
      doc.setFont('helvetica', 'bold');
      doc.text('Clinical Readings', margin, y);
      y += 6;

      const tableStartY = y;
      const tableCols = [10, 48, 32, 22, 58];
      const tableHeaders = ['#', 'Date & Time', 'Blood Pressure', 'Pulse', 'Glucose'];
      const totalTableWidth = tableCols.reduce((a, b) => a + b, 0);
      const tableStartX = margin;

      doc.setFillColor(255, 131, 8);
      doc.rect(tableStartX, tableStartY - 2, totalTableWidth, 6, 'F');
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(7);
      doc.setTextColor(255, 255, 255);
      let headerX = tableStartX;
      tableHeaders.forEach((h, i) => {
        const textWidth = doc.getStringUnitWidth(h) * 7 / doc.internal.scaleFactor;
        const textX = headerX + (tableCols[i] / 2) - (textWidth / 2);
        doc.text(h, textX, tableStartY + 2);
        headerX += tableCols[i];
      });

      let tableY = tableStartY + 6;
      const shown = rows;

      shown.forEach((r, i) => {
        const d = new Date(r.timestamp);
        const rowY = tableY + (i * 6.5);

        doc.setDrawColor(...colors.borderGray);
        doc.setLineWidth(0.1);

        let x = tableStartX;
        tableCols.forEach(colWidth => {
          doc.rect(x, rowY - 2, colWidth, 6.5, 'S');
          x += colWidth;
        });

        const centerText = (text, colIndex, color, font, style, size) => {
          doc.setFont(font || 'helvetica', style || 'normal');
          doc.setFontSize(size || 6.5);
          doc.setTextColor(...(color || colors.navy));
          const str = String(text);
          const textWidth = doc.getStringUnitWidth(str) * (size || 6.5) / doc.internal.scaleFactor;
          const xPos = tableStartX + tableCols.slice(0, colIndex).reduce((a, b) => a + b, 0);
          const textX = xPos + (tableCols[colIndex] / 2) - (textWidth / 2);
          doc.text(str, textX, rowY + 1.2);
        };

        centerText(String(i + 1), 0, colors.gray, 'helvetica', 'normal', 6.5);
        centerText(formatDateForReport(d), 1, colors.navy, 'helvetica', 'normal', 6);

        /* Blood Pressure */
        centerText(hasBP(r) ? `${r.sys}/${r.dia}` : '--', 2, getStatusColor(r.sys, r.dia), 'helvetica', 'bold', 7);

        /* Pulse */
        centerText(hasPulse(r) ? String(r.pulse) : '--', 3, getPulseColor(r.pulse), 'helvetica', 'bold', 7);

        /* Glucose — value bold, tag semibold smaller */
        if (hasGlucose(r)) {
          doc.setFont('helvetica', 'bold');
          doc.setFontSize(7);
          const valText = formatGlucosePrimary(r.glucoseValue, r.glucoseUnit);
          const tagText = ` (${GLUCOSE_LABELS[r.glucoseCategory]})`;
          const color = getGlucoseColor(r.glucoseValue, r.glucoseCategory, r.glucoseUnit);
          doc.setTextColor(...color);
          const valWidth = doc.getStringUnitWidth(valText) * 7 / doc.internal.scaleFactor;
          doc.setFont('helvetica', 'normal');
          doc.setFontSize(6);
          const tagWidth = doc.getStringUnitWidth(tagText) * 6 / doc.internal.scaleFactor;
          const totalWidth = valWidth + tagWidth;
          const cellX = tableStartX + tableCols.slice(0, 4).reduce((a, b) => a + b, 0);
          const textX = cellX + (tableCols[4] / 2) - (totalWidth / 2);
          doc.setFont('helvetica', 'bold');
          doc.setFontSize(7);
          doc.setTextColor(...color);
          doc.text(valText, textX, rowY + 1.2);
          doc.setFont('helvetica', 'normal');
          doc.setFontSize(6);
          doc.text(tagText, textX + valWidth, rowY + 1.2);
        } else {
          centerText('--', 4, colors.gray, 'helvetica', 'normal', 6.5);
        }
      });

      let finalY = tableY + (shown.length * 6.5) + 12;

      /* ---- FOOTER — 3 lines of space then footer, then page ends ---- */
      doc.setDrawColor(...colors.lightGray);
      doc.setLineWidth(0.3);
      doc.line(margin, finalY - 4, pageWidth - margin, finalY - 4);

      doc.setFont('helvetica', 'normal');
      doc.setFontSize(7);
      doc.setTextColor(...colors.gray);
      doc.text('Developed & Maintained by', pageWidth / 2, finalY, { align: 'center' });

      /* Jeweller names, clickable with dotted underline */
      finalY += 5;
      doc.setFontSize(8);
      doc.setFont('helvetica', 'bold');
      doc.setTextColor(...colors.primary);

      const whiteMoon = 'WhiteMoon Jeweller';
      const separator = '  |  ';
      const asad = 'Asad Jewellers, Okara';
      const wmWidth = doc.getTextWidth(whiteMoon);
      const sepWidth = doc.getTextWidth(separator);
      const asadWidth = doc.getTextWidth(asad);
      const totalJW = wmWidth + sepWidth + asadWidth;
      const jwStartX = (pageWidth - totalJW) / 2;

      doc.text(whiteMoon, jwStartX, finalY);
      doc.link(jwStartX, finalY - 3, wmWidth, 5, { url: 'https://share.google/bWfGrw0Q622ZebL1s' });
      doc.setDrawColor(...colors.primary);
      doc.setLineDashPattern([0.3, 0.6], 0);
      doc.line(jwStartX, finalY + 0.8, jwStartX + wmWidth, finalY + 0.8);
      doc.setLineDashPattern([], 0);

      doc.setTextColor(...colors.gray);
      doc.text(separator, jwStartX + wmWidth, finalY);

      doc.setTextColor(...colors.primary);
      doc.text(asad, jwStartX + wmWidth + sepWidth, finalY);
      doc.link(jwStartX + wmWidth + sepWidth, finalY - 3, asadWidth, 5, { url: 'https://share.google/jHB4SvgAeMeM0FXPk' });
      doc.setDrawColor(...colors.primary);
      doc.setLineDashPattern([0.3, 0.6], 0);
      doc.line(jwStartX + wmWidth + sepWidth, finalY + 0.8, jwStartX + wmWidth + sepWidth + asadWidth, finalY + 0.8);
      doc.setLineDashPattern([], 0);

      /* Contact row — WhatsApp + Email icons + clickable text.
         Paste your base64 strings into WA_ICON and EM_ICON below.
         Both must be PNG. Email icon must not be WebP. */
      finalY += 8;
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(7);

      const WA_ICON = 'data:image/png;base64,';
      const EM_ICON = 'data:image/png;base64,';

      const waText = '+92 311 0177836';
      const emailText = 'myhealthjournalapp@gmail.com';
      const contactSep = '|';
      const iconSize = 3.6;
      const iconGap = 1.4;
      const sepGap = 3.5;

      doc.setFontSize(7);
      const waTextWidth = doc.getTextWidth(waText);
      const emailTextWidth = doc.getTextWidth(emailText);
      const contactSepWidth = doc.getTextWidth(contactSep);

const totalWidth =
  iconSize + iconGap + waTextWidth +
  sepGap + contactSepWidth + sepGap +
  iconSize + iconGap + emailTextWidth;
  
      let cX = (pageWidth - totalWidth) / 2;

      try {
        doc.addImage(WA_ICON, 'PNG', cX, finalY - 3, iconSize, iconSize);
      } catch (e) { console.error('WA icon:', e); }
      cX += iconSize + iconGap;

      doc.setTextColor(...colors.gray);
      doc.text(waText, cX, finalY);
      doc.link(cX, finalY - 3, waTextWidth, 5, { url: 'https://wa.me/923110177836' });
      cX += waTextWidth;

      cX += sepGap;
      doc.setTextColor(...colors.lightGray);
      doc.text(contactSep, cX, finalY);
      cX += contactSepWidth + sepGap;

      try {
        doc.addImage(EM_ICON, 'PNG', cX, finalY - 3, iconSize, iconSize);
      } catch (e) { console.error('Email icon:', e); }
      cX += iconSize + iconGap;

      doc.setTextColor(...colors.gray);
      doc.text(emailText, cX, finalY);
      doc.link(cX, finalY - 3, emailTextWidth, 5, { url: 'mailto:myhealthjournalapp@gmail.com' });

      /* Page ends here — no trailing whitespace */
      const fileName = generateFileName('pdf', fromDate, toDate);
      downloadFile(doc.output('blob'), fileName, 'application/pdf');
      showToast('PDF downloaded; Drive upload in progress');
    } catch (error) {
      console.error('PDF error:', error);
      showToast('PDF error: ' + error.message);
    }
  };

  /* ------------------------------------------------------------------ */
  /* Backup to Drive (legacy entry point)                                */
  /* ------------------------------------------------------------------ */

  window.backupToDrive = async function () {
    try {
      if (typeof backupToDriveV2 === 'function') await backupToDriveV2();
      else showToast('Google Drive backup not available');
    } catch (error) {
      console.error('Backup error:', error);
      showToast('Backup failed: ' + error.message);
    }
  };

  /* ------------------------------------------------------------------ */
  /* Biometric + PIN toggles                                             */
  /* ------------------------------------------------------------------ */

  byId('biometricLoginBtn')?.addEventListener('click', async () => {
    const email = localStorage.getItem('mhj:lastActive');
    const record = email && JSON.parse(localStorage.getItem(`mhj:account:${email}`) || 'null');
    if (!record?.settings?.biometric) return showToast('Biometric verification is not enabled for the last active account');
    if (!window.PublicKeyCredential) return showToast('Biometric authentication is not supported by this browser/device');
    showToast('This web version requires a registered WebAuthn credential. Native mobile builds should use the device biometric API.');
  });

  byId('biometricToggle')?.addEventListener('change', e => {
    APP.settings.biometric = e.target.checked;
    saveData();
    showToast(e.target.checked
      ? 'Biometric option enabled; device registration is required before use'
      : 'Biometric option disabled');
  });

  /* PIN enable / disable — fire emails only on deliberate user action */
  byId('appLockToggle')?.addEventListener('change', e => {
    const wasOn = !!APP.settings.appLock;
    const nowOn = e.target.checked;
    APP.settings.appLock = nowOn;
    saveData();
    syncLoginOptions();
    if (!wasOn && nowOn) sendEmailTemplate('PIN_ENABLED_TOGGLE_TURNED_ON');
    if (wasOn && !nowOn) sendEmailTemplate('PIN_DISABLED_TOGGLE_TURNED_OFF');
  });

  /* ------------------------------------------------------------------ */
  /* Import from logs shortcut                                           */
  /* ------------------------------------------------------------------ */

  byId('openImportFromLogs')?.addEventListener('click', () => {
    byId('exportModal')?.classList.remove('open');
    byId('importModal')?.classList.add('open');
  });

  /* ------------------------------------------------------------------ */
  /* Settings → Advanced → Email Logs                                    */
  /* ------------------------------------------------------------------ */

  byId('advancedEmailLogsBtn')?.addEventListener('click', () => {
    if (typeof openEmailLogs === 'function') openEmailLogs();
  });

  byId('advancedLogsBtn')?.addEventListener('click', () => {
    if (typeof openLogs === 'function') openLogs();
  });

  /* ------------------------------------------------------------------ */
  /* Medical Records UI                                                  */
  /* ------------------------------------------------------------------ */

  // Medical Records and email preference controls are bound in app.js and reliability.js.

  /* ------------------------------------------------------------------ */
  /* About modal init                                                    */
  /* ------------------------------------------------------------------ */

  document.addEventListener('DOMContentLoaded', () => {
    setTimeout(async () => {
      const yearEl = byId('aboutYear');
      if (yearEl) yearEl.textContent = new Date().getFullYear();
      const versionEl = byId('aboutVersion');
      if (versionEl) versionEl.textContent = await fetchAppVersion();
    }, 500);
  });

  syncChartLayout();
})();